// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/string.h>

static void equal_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("hello", "hello", 5));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("hello", "hello", 100));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("", "", 5));
}

static void case_insensitive_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("HeLLo", "hEllO", 5));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("ABCXYZ", "abcxyz", 6));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("a1-_Z", "A1-_z", 5));
}

static void zero_len_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abc", "xyz", 0));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("", "abc", 0));
}

static void len_boundary_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abcd", "abcx", 3));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("abcd", "abcx", 4));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abc", "ABC", 3));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("a", "A", 1));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("a", "b", 1));
	KUNIT_EXPECT_LT(test, strncasecmp("a", "b", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("b", "a", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abd", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abd", "abc", 3), 0);
}

static void ordering_test(struct kunit *test)
{
	KUNIT_EXPECT_LT(test, strncasecmp("apple", "banana", 5), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("banana", "apple", 5), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("A", "b", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("B", "a", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("a", "B", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("b", "A", 1), 0);
	/* '_' (0x5f) sorts before 'a' once lowercased, after 'A' raw */
	KUNIT_EXPECT_LT(test, strncasecmp("_", "A", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("[", "a", 1), 0);
}

static void length_mismatch_test(struct kunit *test)
{
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abcd", 10), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abcd", "abc", 10), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("", "a", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("a", "", 1), 0);
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abc", "abcd", 3));
	KUNIT_EXPECT_EQ(test, -'d', strncasecmp("abc", "abcd", 4));
	KUNIT_EXPECT_EQ(test, 'd', strncasecmp("abcd", "abc", 4));
}

static void stops_at_nul_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("ab\0x", "AB\0y", 4));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("ab\0x", "AB\0y", 100));
}

static void high_bytes_test(struct kunit *test)
{
	KUNIT_EXPECT_GT(test, strncasecmp("\xff", "a", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("a", "\xff", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("\x80", "\x7f", 1), 0);
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("\xc3\xa9", "\xc3\xa9", 2));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("\xc3\xa9", "\xc3\x89", 2));
}

static void alpha_boundary_test(struct kunit *test)
{
	int c;

	for (c = 'a'; c <= 'z'; c++) {
		char a[2] = { c, 0 };
		char b[2] = { c - 'a' + 'A', 0 };

		KUNIT_EXPECT_EQ(test, 0, strncasecmp(a, b, 1));
	}
	KUNIT_EXPECT_NE(test, 0, strncasecmp("@", "`", 1));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("[", "{", 1));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("@", "a", 1));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("`", "A", 1));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("[", "z", 1));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("{", "Z", 1));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("0", "p", 1));
}

static void late_difference_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abcdefgh", "ABCDEFGH", 8));
	KUNIT_EXPECT_LT(test, strncasecmp("abcdefgh", "ABCDEFGi", 8), 0);
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abcdefgh", "ABCDEFGi", 7));
	KUNIT_EXPECT_EQ(test, -1, strncasecmp("abcdefgh", "ABCDEFGi", 8));
	KUNIT_EXPECT_EQ(test, 1, strncasecmp("abcdefgi", "ABCDEFGH", 8));
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(equal_test),
	KUNIT_CASE(case_insensitive_test),
	KUNIT_CASE(zero_len_test),
	KUNIT_CASE(len_boundary_test),
	KUNIT_CASE(ordering_test),
	KUNIT_CASE(length_mismatch_test),
	KUNIT_CASE(stops_at_nul_test),
	KUNIT_CASE(high_bytes_test),
	KUNIT_CASE(alpha_boundary_test),
	KUNIT_CASE(late_difference_test),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

MODULE_DESCRIPTION("KUnit tests for strncasecmp");
MODULE_LICENSE("GPL");

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/string.h>

static void strcspn_empty_s(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("", ""), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("", "abc"), (size_t)0);
}

static void strcspn_empty_reject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", ""), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("a", ""), (size_t)1);
}

static void strcspn_no_match(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "xyz"), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("abc", "ABC"), (size_t)3);
}

static void strcspn_match_first(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "h"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("hello", "xyzh"), (size_t)0);
}

static void strcspn_match_last(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "o"), (size_t)4);
	KUNIT_EXPECT_EQ(test, strcspn("a", "a"), (size_t)0);
}

static void strcspn_match_middle(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "l"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("key=value", "="), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "de"), (size_t)3);
}

static void strcspn_first_of_many(struct kunit *test)
{
	/* The earliest match in s wins, regardless of reject order. */
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "fedcb"), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn("a,b;c", ";,"), (size_t)1);
}

static void strcspn_repeated_chars(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("aaaab", "b"), (size_t)4);
	KUNIT_EXPECT_EQ(test, strcspn("aaaab", "aaa"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("abab", "bb"), (size_t)1);
}

static void strcspn_nul_not_scanned_past(struct kunit *test)
{
	char buf[] = "ab\0cd";

	KUNIT_EXPECT_EQ(test, strcspn(buf, "cd"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn(buf, "a"), (size_t)0);
}

static void strcspn_reject_stops_at_nul(struct kunit *test)
{
	char rej[] = "x\0a";

	KUNIT_EXPECT_EQ(test, strcspn("bca", rej), (size_t)3);
}

static void strcspn_case_sensitive(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcABC", "C"), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("abcABC", "A"), (size_t)3);
}

static void strcspn_high_bytes(struct kunit *test)
{
	const char s[] = "ab\x80\xff" "c";

	KUNIT_EXPECT_EQ(test, strcspn(s, "\xff"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn(s, "\x80"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn(s, "\x7f"), (size_t)5);
}

static void strcspn_whole_string_reject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abc", "abc"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("abc", "cba"), (size_t)0);
}

static void strcspn_long_string(struct kunit *test)
{
	char buf[257];

	memset(buf, 'a', sizeof(buf) - 1);
	buf[sizeof(buf) - 1] = '\0';
	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), (size_t)256);
	buf[255] = 'b';
	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), (size_t)255);
	buf[128] = 'b';
	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), (size_t)128);
}

static void strcspn_does_not_modify(struct kunit *test)
{
	char s[] = "hello world";
	char r[] = " ow";

	KUNIT_EXPECT_EQ(test, strcspn(s, r), (size_t)4);
	KUNIT_EXPECT_STREQ(test, s, "hello world");
	KUNIT_EXPECT_STREQ(test, r, " ow");
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(strcspn_empty_s),
	KUNIT_CASE(strcspn_empty_reject),
	KUNIT_CASE(strcspn_no_match),
	KUNIT_CASE(strcspn_match_first),
	KUNIT_CASE(strcspn_match_last),
	KUNIT_CASE(strcspn_match_middle),
	KUNIT_CASE(strcspn_first_of_many),
	KUNIT_CASE(strcspn_repeated_chars),
	KUNIT_CASE(strcspn_nul_not_scanned_past),
	KUNIT_CASE(strcspn_reject_stops_at_nul),
	KUNIT_CASE(strcspn_case_sensitive),
	KUNIT_CASE(strcspn_high_bytes),
	KUNIT_CASE(strcspn_whole_string_reject),
	KUNIT_CASE(strcspn_long_string),
	KUNIT_CASE(strcspn_does_not_modify),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

MODULE_DESCRIPTION("KUnit tests for strcspn");
MODULE_LICENSE("GPL");

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */

#include <kunit/test.h>
#include <linux/string_helpers.h>
#include <linux/string.h>

struct sgs_case {
	u64 size;
	u64 blk;
	unsigned int units;
	const char *exp;
};

static void sgs_check(struct kunit *test, const struct sgs_case *c, int n)
{
	char buf[32];
	int i, ret;

	for (i = 0; i < n; i++) {
		memset(buf, 0xaa, sizeof(buf));
		ret = string_get_size(c[i].size, c[i].blk, c[i].units, buf, sizeof(buf));
		KUNIT_EXPECT_STREQ_MSG(test, buf, c[i].exp, "case %d", i);
		KUNIT_EXPECT_EQ_MSG(test, ret, (int)strlen(c[i].exp), "case %d", i);
	}
}

static void sgs_zero(struct kunit *test)
{
	static const struct sgs_case c[] = {
		{ 0, 1, STRING_UNITS_10, "0 B" },
		{ 0, 1, STRING_UNITS_2, "0 B" },
		{ 0, 0, STRING_UNITS_10, "0 B" },
		{ 1, 0, STRING_UNITS_10, "0 B" },
		{ 12345, 0, STRING_UNITS_2, "0 B" },
		{ 0, 512, STRING_UNITS_2, "0 B" },
		{ 0, 512, STRING_UNITS_2 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES, "0" },
		{ 0, 1, STRING_UNITS_10 | STRING_UNITS_NO_SPACE, "0B" },
	};
	sgs_check(test, c, ARRAY_SIZE(c));
}

static void sgs_below_divisor(struct kunit *test)
{
	static const struct sgs_case c[] = {
		{ 1, 1, STRING_UNITS_10, "1.00 B" },
		{ 1, 1, STRING_UNITS_2, "1.00 B" },
		{ 999, 1, STRING_UNITS_10, "999 B" },
		{ 1000, 1, STRING_UNITS_2, "1000 B" },
		{ 1023, 1, STRING_UNITS_2, "1023 B" },
		{ 10, 1, STRING_UNITS_10, "10.0 B" },
		{ 100, 1, STRING_UNITS_2, "100 B" },
	};
	sgs_check(test, c, ARRAY_SIZE(c));
}

