		{ 123456, 1, STRING_UNITS_10, "123 kB" },
		{ 12345, 1, STRING_UNITS_10, "12.3 kB" },
		{ 1234, 1, STRING_UNITS_10, "1.23 kB" },
	};
	sgs_check(test, c, ARRAY_SIZE(c));
}

static void sgs_rounding(struct kunit *test)
{
	static const struct sgs_case c[] = {
