static void sgs_block_size(struct kunit *test)
{
	static const struct sgs_case c[] = {
		{ 2, 512, STRING_UNITS_2, "1.00 KiB" },
		{ 1, 512, STRING_UNITS_2, "512 B" },
		{ 1, 512, STRING_UNITS_10, "512 B" },
