		{ 1000, 1000, STRING_UNITS_10, "1.00 MB" },
		{ 1024, 1024, STRING_UNITS_2, "1.00 MiB" },
		{ 1, 1ULL << 40, STRING_UNITS_2, "1.00 TiB" },
		{ 1ULL << 40, 1, STRING_UNITS_2, "1.00 TiB" },
		{ 1ULL << 20, 1ULL << 20, STRING_UNITS_2, "1.00 TiB" },
		{ 1ULL << 32, 1, STRING_UNITS_2, "4.00 GiB" },
		{ (1ULL << 32) - 1, 1, STRING_UNITS_2, "4.00 GiB" },
