static void sgs_flags(struct kunit *test)
{
	static const struct sgs_case c[] = {
		{ 1000, 1, STRING_UNITS_10 | STRING_UNITS_NO_SPACE, "1.00kB" },
		{ 1000, 1, STRING_UNITS_10 | STRING_UNITS_NO_BYTES, "1.00 k" },
		{ 1000, 1, STRING_UNITS_10 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES, "1.00k" },
		{ 1024, 1, STRING_UNITS_2 | STRING_UNITS_NO_SPACE, "1.00KiB" },
		{ 1024, 1, STRING_UNITS_2 | STRING_UNITS_NO_BYTES, "1.00 Ki" },
		{ 1024, 1, STRING_UNITS_2 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES, "1.00Ki" },
		{ 5, 1, STRING_UNITS_10 | STRING_UNITS_NO_SPACE, "5.00B" },
		{ 5, 1, STRING_UNITS_10 | STRING_UNITS_NO_BYTES, "5.00 " },
		{ 5, 1, STRING_UNITS_2 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES, "5.00" },
	};
	sgs_check(test, c, ARRAY_SIZE(c));
}

static void sgs_buffer(struct kunit *test)
{
	char buf[16];
	int ret;

	/* zero length: nothing written, full length reported */
	memset(buf, 'x', sizeof(buf));
	ret = string_get_size(1000, 1, STRING_UNITS_10, buf, 0);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_EQ(test, buf[0], 'x');

	/* exact fit: needs len == strlen + 1 */
	memset(buf, 'x', sizeof(buf));
	ret = string_get_size(1000, 1, STRING_UNITS_10, buf, 8);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_STREQ(test, buf, "1.00 kB");

	/* one byte short: truncated, terminated, still reports full length */
	memset(buf, 'x', sizeof(buf));
	ret = string_get_size(1000, 1, STRING_UNITS_10, buf, 7);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_STREQ(test, buf, "1.00 k");
	KUNIT_EXPECT_EQ(test, buf[7], 'x');

	memset(buf, 'x', sizeof(buf));
	ret = string_get_size(1000, 1, STRING_UNITS_10, buf, 1);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_EQ(test, buf[0], '\0');
	KUNIT_EXPECT_EQ(test, buf[1], 'x');

	memset(buf, 'x', sizeof(buf));
	ret = string_get_size(1000, 1, STRING_UNITS_10, buf, 3);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_STREQ(test, buf, "1.");

	/* zero-size path also honours len */
	memset(buf, 'x', sizeof(buf));
	ret = string_get_size(0, 1, STRING_UNITS_10, buf, 2);
	KUNIT_EXPECT_EQ(test, ret, 3);
	KUNIT_EXPECT_STREQ(test, buf, "0");

	ret = string_get_size(1023ULL * 1024, 1, STRING_UNITS_2, buf, sizeof(buf));
	KUNIT_EXPECT_STREQ(test, buf, "1023 KiB");
	KUNIT_EXPECT_EQ(test, ret, 8);
}

static void sgs_huge(struct kunit *test)
{
	char buf[32];
	int ret;

	ret = string_get_size(U64_MAX, 1, STRING_UNITS_2, buf, sizeof(buf));
	KUNIT_EXPECT_STREQ(test, buf, "16.0 EiB");
	KUNIT_EXPECT_EQ(test, ret, 8);

	ret = string_get_size(U64_MAX, 1, STRING_UNITS_10, buf, sizeof(buf));
	KUNIT_EXPECT_STREQ(test, buf, "18.4 EB");
	KUNIT_EXPECT_EQ(test, ret, 7);

	ret = string_get_size(U64_MAX, U64_MAX, STRING_UNITS_2, buf, sizeof(buf));
	KUNIT_EXPECT_GT(test, ret, 0);
	KUNIT_EXPECT_EQ(test, ret, (int)strlen(buf));

	ret = string_get_size(U64_MAX, U64_MAX, STRING_UNITS_10, buf, sizeof(buf));
	KUNIT_EXPECT_GT(test, ret, 0);
	KUNIT_EXPECT_EQ(test, ret, (int)strlen(buf));
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(sgs_zero),
	KUNIT_CASE(sgs_below_divisor),
	KUNIT_CASE(sgs_at_divisor),
	KUNIT_CASE(sgs_precision),
	KUNIT_CASE(sgs_rounding),
