#include <kunit/test.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

/* Escape with a roomy buffer and check both the result and return value. */
static void check(struct kunit *test, const char *src, size_t isz,
		  unsigned int flags, const char *only, const char *exp)
{
	char buf[256];
	int ret;

	memset(buf, 0x55, sizeof(buf));
	ret = string_escape_mem(src, isz, buf, sizeof(buf), flags, only);
	KUNIT_ASSERT_EQ(test, ret, (int)strlen(exp));
	KUNIT_EXPECT_EQ(test, memcmp(buf, exp, ret), 0);
	/* nothing written past the output */
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[ret], 0x55);
}

static void escape_empty_input(struct kunit *test)
{
	char buf[4];

	memset(buf, 0x55, sizeof(buf));
	KUNIT_EXPECT_EQ(test, string_escape_mem("abc", 0, buf, sizeof(buf), ESCAPE_ANY, NULL), 0);
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[0], 0x55);
	KUNIT_EXPECT_EQ(test, string_escape_mem("", 0, NULL, 0, ESCAPE_ANY, NULL), 0);
}

static void escape_space_class(struct kunit *test)
{
	check(test, "\f\n\r\t\v", 5, ESCAPE_SPACE, NULL, "\\f\\n\\r\\t\\v");
	/* plain space is not escaped */
	check(test, " a ", 3, ESCAPE_SPACE, NULL, " a ");
	/* not escaped without the flag */
	check(test, "\n", 1, ESCAPE_SPECIAL, NULL, "\n");
}

static void escape_special_class(struct kunit *test)
{
	check(test, "\"\\\a\033", 4, ESCAPE_SPECIAL, NULL, "\\\"\\\\\\a\\e");
	check(test, "\"", 1, ESCAPE_SPACE, NULL, "\"");
}

static void escape_null_class(struct kunit *test)
{
	char buf[8];

	memset(buf, 0x55, sizeof(buf));
	KUNIT_EXPECT_EQ(test, string_escape_mem("a\0b", 3, buf, sizeof(buf), ESCAPE_NULL, NULL), 4);
	KUNIT_EXPECT_EQ(test, memcmp(buf, "a\\0b", 4), 0);

	KUNIT_EXPECT_EQ(test, string_escape_mem("\0", 1, buf, sizeof(buf), ESCAPE_SPACE, NULL), 1);
	KUNIT_EXPECT_EQ(test, buf[0], 0);
}

static void escape_octal_class(struct kunit *test)
{
	check(test, "\001\177\200\377", 4, ESCAPE_OCTAL, NULL,
	      "\\001\\177\\200\\377");
	check(test, "8\007", 2, ESCAPE_OCTAL, NULL, "\\070\\007");
}

static void escape_hex_class(struct kunit *test)
{
	check(test, "\n\x7f\x80\xff", 4, ESCAPE_HEX, NULL,
	      "\\x0a\\x7f\\x80\\xff");
	check(test, "\xab\xcd", 2, ESCAPE_HEX, NULL, "\\xab\\xcd");
}

static void escape_octal_before_hex(struct kunit *test)
{
	check(test, "\x01", 1, ESCAPE_OCTAL | ESCAPE_HEX, NULL, "\\001");
}

static void escape_class_priority(struct kunit *test)
{
	char buf[32];

	check(test, "\n\"\001", 3, ESCAPE_ANY, NULL, "\\n\\\"\\001");
	check(test, "\n\x01", 2, ESCAPE_SPACE | ESCAPE_HEX, NULL, "\\n\\x01");
	/* unmatched characters pass through */
	check(test, "a\nb\x01", 4, ESCAPE_SPACE, NULL, "a\\nb\x01");

	KUNIT_EXPECT_EQ(test, string_escape_mem("\0\n", 2, buf, sizeof(buf), ESCAPE_ANY, NULL), 4);
	KUNIT_EXPECT_EQ(test, memcmp(buf, "\\0\\n", 4), 0);
}

static void escape_no_flags(struct kunit *test)
{
	check(test, "a\n\x01\xff", 4, 0, NULL, "a\n\x01\xff");
}

static void escape_np(struct kunit *test)
{
	/* 0x1f non-printable, 0x20 and 0x7e printable, 0x7f non-printable */
	check(test, "\x1f \x7e\x7f", 4, ESCAPE_NP | ESCAPE_HEX, NULL,
	      "\\x1f ~\\x7f");
	check(test, "a\n", 2, ESCAPE_NP | ESCAPE_SPACE, NULL, "a\\n");
	check(test, "A\"", 2, ESCAPE_ANY_NP, NULL, "A\"");
}

static void escape_na(struct kunit *test)
{
	/* ascii passes through, including control chars */
	check(test, "a\x01\x7f\x80\xff", 5, ESCAPE_NA | ESCAPE_HEX, NULL,
	      "a\x01\x7f\\x80\\xff");
}

static void escape_nap(struct kunit *test)
{
	check(test, "a\x01\x1f \x7e\x7f\x80", 7, ESCAPE_NAP | ESCAPE_HEX, NULL,
	      "a\\x01\\x1f ~\\x7f\\x80");
	check(test, "\n\x80", 2, ESCAPE_NAP | ESCAPE_SPACE | ESCAPE_OCTAL, NULL,
	      "\\n\\200");
}

static void escape_only_dict(struct kunit *test)
{
	/* only chars in @only are subject to escaping */
	check(test, "a\nb\tc", 5, ESCAPE_ANY, "\n", "a\\nb\tc");
	check(test, "a\nb\tc", 5, ESCAPE_ANY, "\n\t", "a\\nb\\tc");
	/* char in only but not in an enabled class passes through */
	check(test, "ab", 2, ESCAPE_SPACE, "a", "ab");
	/* char in only, escaped by octal */
	check(test, "ab", 2, ESCAPE_OCTAL, "b", "a\\142");
	/* empty only string means no limit */
	check(test, "a\n", 2, ESCAPE_SPACE, "", "a\\n");
}

static void escape_only_with_np(struct kunit *test)
{
	check(test, "ab\x01", 3, ESCAPE_NP | ESCAPE_HEX, "ab\x01", "ab\\x01");
	check(test, "ab", 2, ESCAPE_NP | ESCAPE_HEX, "a", "ab");
}

static void escape_append(struct kunit *test)
{
	check(test, "ab\x01", 3, ESCAPE_NP | ESCAPE_HEX | ESCAPE_APPEND, "a",
	      "\\x61b\\x01");
	check(test, "a\x80""b", 3, ESCAPE_NA | ESCAPE_OCTAL | ESCAPE_APPEND, "b",
	      "a\\200\\142");
	check(test, "ab", 2, ESCAPE_NAP | ESCAPE_HEX | ESCAPE_APPEND, "ab",
	      "\\x61\\x62");
	check(test, "ab", 2, ESCAPE_NP | ESCAPE_HEX | ESCAPE_APPEND, "z", "ab");
}

static void escape_binary_and_length(struct kunit *test)
{
	check(test, "ab\0cd", 2, ESCAPE_SPACE, NULL, "ab");
	check(test, "ab\0cd", 5, ESCAPE_HEX, NULL, "\\x61\\x62\\x00\\x63\\x64");
	check(test, "abc", 1, ESCAPE_HEX, NULL, "\\x61");
}

static void escape_truncation_return(struct kunit *test)
{
	char buf[16];
	int i;

	/* return value is the full length regardless of osz */
	for (i = 0; i <= 12; i++) {
		memset(buf, 0x55, sizeof(buf));
		KUNIT_EXPECT_EQ(test, string_escape_mem("\1\2\3", 3, buf, i, ESCAPE_OCTAL, NULL), 12);
		KUNIT_EXPECT_EQ(test, memcmp(buf, "\\001\\002\\003", i), 0);
		KUNIT_EXPECT_EQ(test, (unsigned char)buf[i], 0x55);
	}
}

static void escape_truncation_mid_sequence(struct kunit *test)
{
	char buf[8];

	memset(buf, 0x55, sizeof(buf));
	KUNIT_EXPECT_EQ(test, string_escape_mem("a\n", 2, buf, 2, ESCAPE_SPACE, NULL), 3);
	KUNIT_EXPECT_EQ(test, buf[0], 'a');
	KUNIT_EXPECT_EQ(test, buf[1], '\\');
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[2], 0x55);

	memset(buf, 0x55, sizeof(buf));
	KUNIT_EXPECT_EQ(test, string_escape_mem("\xff", 1, buf, 3, ESCAPE_HEX, NULL), 4);
	KUNIT_EXPECT_EQ(test, memcmp(buf, "\\xf", 3), 0);
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[3], 0x55);

	memset(buf, 0x55, sizeof(buf));
	KUNIT_EXPECT_EQ(test, string_escape_mem("\0", 1, buf, 1, ESCAPE_NULL, NULL), 2);
	KUNIT_EXPECT_EQ(test, buf[0], '\\');
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[1], 0x55);
}

static void escape_exact_fit_and_terminator(struct kunit *test)
{
	char buf[8];
	int ret;

	memset(buf, 0x55, sizeof(buf));
	ret = string_escape_mem("a\n", 2, buf, 3, ESCAPE_SPACE, NULL);
	KUNIT_EXPECT_EQ(test, ret, 3);
	KUNIT_EXPECT_EQ(test, memcmp(buf, "a\\n", 3), 0);
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[3], 0x55);

	ret = string_escape_mem("a\n", 2, buf, 4, ESCAPE_SPACE, NULL);
	KUNIT_EXPECT_EQ(test, ret, 3);
