#include <kunit/test.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

#define CANARY 0xAA

/* Run string_unescape on a copy of @in, check ret, output and canary. */
static void check_unescape(struct kunit *test, const char *in, size_t size,
			   unsigned int flags, const char *exp, int exp_len)
{
	char src[64];
	char dst[64];
	int ret;

	memset(dst, CANARY, sizeof(dst));
	strscpy(src, in, sizeof(src));

	ret = string_unescape(src, dst, size, flags);
	KUNIT_EXPECT_EQ(test, ret, exp_len);
	/* expected output may contain NUL bytes, so compare by length */
	KUNIT_EXPECT_EQ(test, dst[exp_len], '\0');
	KUNIT_EXPECT_EQ(test, memcmp(dst, exp, exp_len), 0);
	/* byte after the terminator is untouched */
	KUNIT_EXPECT_EQ(test, (u8)dst[exp_len + 1], (u8)CANARY);
}

static void empty_test(struct kunit *test)
{
	check_unescape(test, "", 0, UNESCAPE_ANY, "", 0);
	check_unescape(test, "", 10, UNESCAPE_ANY, "", 0);
}

static void no_flags_test(struct kunit *test)
{
	check_unescape(test, "a\\nb", 0, 0, "a\\nb", 4);
	check_unescape(test, "\\101\\x41\\\"\\\\", 0, 0, "\\101\\x41\\\"\\\\", 12);
}

static void plain_text_test(struct kunit *test)
{
	check_unescape(test, "hello world", 0, UNESCAPE_ANY, "hello world", 11);
}

static void space_test(struct kunit *test)
{
	check_unescape(test, "\\f", 0, UNESCAPE_SPACE, "\f", 1);
	check_unescape(test, "\\n", 0, UNESCAPE_SPACE, "\n", 1);
	check_unescape(test, "\\r", 0, UNESCAPE_SPACE, "\r", 1);
	check_unescape(test, "\\t", 0, UNESCAPE_SPACE, "\t", 1);
	check_unescape(test, "\\v", 0, UNESCAPE_SPACE, "\v", 1);
	check_unescape(test, "a\\tb\\nc", 0, UNESCAPE_SPACE, "a\tb\nc", 5);
}

static void space_not_others_test(struct kunit *test)
{
	check_unescape(test, "\\a\\e\\\"\\\\", 0, UNESCAPE_SPACE, "\\a\\e\\\"\\\\", 8);
	check_unescape(test, "\\101", 0, UNESCAPE_SPACE, "\\101", 4);
	check_unescape(test, "\\x41", 0, UNESCAPE_SPACE, "\\x41", 4);
}

static void special_test(struct kunit *test)
{
	check_unescape(test, "\\\"", 0, UNESCAPE_SPECIAL, "\"", 1);
	check_unescape(test, "\\\\", 0, UNESCAPE_SPECIAL, "\\", 1);
	check_unescape(test, "\\a", 0, UNESCAPE_SPECIAL, "\a", 1);
	check_unescape(test, "\\e", 0, UNESCAPE_SPECIAL, "\e", 1);
	check_unescape(test, "\\n\\t", 0, UNESCAPE_SPECIAL, "\\n\\t", 4);
	/* escaped backslash followed by n is not a newline */
	check_unescape(test, "\\\\n", 0, UNESCAPE_ANY, "\\n", 2);
}

static void octal_test(struct kunit *test)
{
	check_unescape(test, "\\0", 0, UNESCAPE_OCTAL, "\0", 1);
	check_unescape(test, "\\1", 0, UNESCAPE_OCTAL, "\001", 1);
	check_unescape(test, "\\7", 0, UNESCAPE_OCTAL, "\007", 1);
	check_unescape(test, "\\60", 0, UNESCAPE_OCTAL, "0", 1);
	check_unescape(test, "\\101", 0, UNESCAPE_OCTAL, "A", 1);
	check_unescape(test, "\\1012", 0, UNESCAPE_OCTAL, "A2", 2);
	check_unescape(test, "\\18", 0, UNESCAPE_OCTAL, "\001" "8", 2);
	check_unescape(test, "\\8", 0, UNESCAPE_OCTAL, "\\8", 2);
	check_unescape(test, "\\a", 0, UNESCAPE_OCTAL, "\\a", 2);
	check_unescape(test, "\\101\\102", 0, UNESCAPE_OCTAL, "AB", 2);
}

static void octal_high_test(struct kunit *test)
{
	char src[] = "\\377";
	char dst[8];
	int ret;

	memset(dst, CANARY, sizeof(dst));
	ret = string_unescape(src, dst, 0, UNESCAPE_OCTAL);
	KUNIT_EXPECT_EQ(test, ret, 1);
	KUNIT_EXPECT_EQ(test, (u8)dst[0], (u8)0xff);
	KUNIT_EXPECT_EQ(test, dst[1], '\0');

	/* \177 is DEL */
	check_unescape(test, "\\177", 0, UNESCAPE_OCTAL, "\177", 1);
	/* \100 is '@', \077 is '?' */
	check_unescape(test, "\\100", 0, UNESCAPE_OCTAL, "@", 1);
	check_unescape(test, "\\077", 0, UNESCAPE_OCTAL, "?", 1);
	/* value >= 32 after two digits stops accumulating */
	check_unescape(test, "\\400", 0, UNESCAPE_OCTAL, " 0", 2);
	check_unescape(test, "\\777", 0, UNESCAPE_OCTAL, "?7", 2);
}

static void hex_test(struct kunit *test)
{
