	check_unescape(test, "\\x41", 0, UNESCAPE_HEX, "A", 1);
	check_unescape(test, "\\x4a", 0, UNESCAPE_HEX, "J", 1);
	check_unescape(test, "\\x4A", 0, UNESCAPE_HEX, "J", 1);
	check_unescape(test, "\\xa", 0, UNESCAPE_HEX, "\n", 1);
	check_unescape(test, "\\xF", 0, UNESCAPE_HEX, "\x0f", 1);
