#include <linux/string.h>

/* Parse @s, check return, value, and the number of chars consumed. */
static void check_opt(struct kunit *test, const char *s, int ret, int val,
		      size_t consumed)
{
	char buf[64];
	char *p = buf;
	int v = 12345;

	strscpy(buf, s, sizeof(buf));
	KUNIT_EXPECT_EQ_MSG(test, get_option(&p, &v), ret, "input '%s'", s);
	KUNIT_EXPECT_EQ_MSG(test, v, val, "input '%s'", s);
	KUNIT_EXPECT_EQ_MSG(test, (size_t)(p - buf), consumed, "input '%s'", s);
}

static void agent_simple(struct kunit *test)
{
	check_opt(test, "0", 1, 0, 1);
	check_opt(test, "7", 1, 7, 1);
	check_opt(test, "42", 1, 42, 2);
	check_opt(test, "2147483647", 1, INT_MAX, 10);
}

static void agent_negative(struct kunit *test)
{
	check_opt(test, "-1", 1, -1, 2);
	check_opt(test, "-42", 1, -42, 3);
	check_opt(test, "-2147483648", 1, INT_MIN, 11);
	check_opt(test, "-0", 1, 0, 2);
}

static void agent_comma(struct kunit *test)
{
	check_opt(test, "5,", 2, 5, 2);
	check_opt(test, "5,6", 2, 5, 2);
	check_opt(test, "-5,6", 2, -5, 3);
	check_opt(test, "0,", 2, 0, 2);
	check_opt(test, "1,,2", 2, 1, 2);
}

static void agent_range(struct kunit *test)
{
	check_opt(test, "5-10", 3, 5, 1);
	check_opt(test, "0-1", 3, 0, 1);
	check_opt(test, "-5-10", 3, -5, 2);
	check_opt(test, "12-", 3, 12, 2);
}

static void agent_bases(struct kunit *test)
{
	check_opt(test, "0x10", 1, 16, 4);
	check_opt(test, "0X1f", 1, 31, 4);
	check_opt(test, "0xff,", 2, 255, 5);
	check_opt(test, "010", 1, 8, 3);
	check_opt(test, "-0x10", 1, -16, 5);
	check_opt(test, "0x7fffffff", 1, INT_MAX, 10);
	/* "0x" with no hex digit: only the "0" is consumed */
	check_opt(test, "0x", 1, 0, 1);
	check_opt(test, "0xg", 1, 0, 1);
	/* 8 is not an octal digit */
	check_opt(test, "08", 1, 0, 1);
}

static void agent_trailing(struct kunit *test)
{
	check_opt(test, "12abc", 1, 12, 2);
	check_opt(test, "12 34", 1, 12, 2);
	check_opt(test, "9;", 1, 9, 1);
	check_opt(test, "3.5", 1, 3, 1);
}

static void agent_no_number(struct kunit *test)
{
	check_opt(test, "abc", 0, 0, 0);
	check_opt(test, " 5", 0, 0, 0);
	check_opt(test, ",5", 0, 0, 0);
	check_opt(test, "+5", 0, 0, 0);
	/* lone hyphen is consumed */
	check_opt(test, "-", 0, 0, 1);
	check_opt(test, "-abc", 0, 0, 1);
	check_opt(test, "-,5", 0, 0, 1);
	check_opt(test, "--5", 0, 0, 1);
}

static void agent_empty_and_null(struct kunit *test)
{
	char empty[] = "";
	char *p = empty;
	int v = 77;
	char *np = NULL;

	KUNIT_EXPECT_EQ(test, get_option(&p, &v), 0);
	KUNIT_EXPECT_PTR_EQ(test, p, &empty[0]);
	KUNIT_EXPECT_EQ(test, v, 77);

	KUNIT_EXPECT_EQ(test, get_option(&np, &v), 0);
	KUNIT_EXPECT_NULL(test, np);
	KUNIT_EXPECT_EQ(test, v, 77);
}

static void agent_null_pint(struct kunit *test)
{
	char b1[] = "123,4";
	char b2[] = "x";
	char b3[] = "1-2";
	char b4[] = "8";
	char *p = b1;

	KUNIT_EXPECT_EQ(test, get_option(&p, NULL), 2);
	KUNIT_EXPECT_PTR_EQ(test, p, &b1[4]);
	p = b2;
	KUNIT_EXPECT_EQ(test, get_option(&p, NULL), 0);
	p = b3;
	KUNIT_EXPECT_EQ(test, get_option(&p, NULL), 3);
	p = b4;
	KUNIT_EXPECT_EQ(test, get_option(&p, NULL), 1);
}

static void agent_iterate(struct kunit *test)
{
	char buf[] = "1,-2,0x3,4";
	char *p = buf;
	int v, expect[] = { 1, -2, 3, 4 }, i = 0;
	int ret;

	while ((ret = get_option(&p, &v)) != 0) {
		KUNIT_ASSERT_LT(test, i, 4);
		KUNIT_EXPECT_EQ(test, v, expect[i]);
		KUNIT_EXPECT_EQ(test, ret, i < 3 ? 2 : 1);
		i++;
	}
	KUNIT_EXPECT_EQ(test, i, 4);
	KUNIT_EXPECT_EQ(test, *p, '\0');
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_simple),
	KUNIT_CASE(agent_negative),
	KUNIT_CASE(agent_comma),
	KUNIT_CASE(agent_range),
	KUNIT_CASE(agent_bases),
	KUNIT_CASE(agent_trailing),
	KUNIT_CASE(agent_no_number),
	KUNIT_CASE(agent_empty_and_null),
	KUNIT_CASE(agent_null_pint),
	KUNIT_CASE(agent_iterate),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

