#include <kunit/test.h>
#include <linux/siphash.h>
#include <linux/bitops.h>
#include <linux/string.h>
#include <linux/unaligned.h>

#define SR(v0, v1, v2, v3) do { \
	v0 += v1; v1 = rol64(v1, 13); v1 ^= v0; v0 = rol64(v0, 32); \
	v2 += v3; v3 = rol64(v3, 16); v3 ^= v2; \
	v0 += v3; v3 = rol64(v3, 21); v3 ^= v0; \
	v2 += v1; v1 = rol64(v1, 17); v1 ^= v2; v2 = rol64(v2, 32); \
} while (0)

/* Independent byte-wise reference implementation of SipHash-2-4. */
static u64 ref_siphash(const u8 *d, size_t len, u64 k0, u64 k1)
{
	u64 v0 = 0x736f6d6570736575ULL ^ k0, v1 = 0x646f72616e646f6dULL ^ k1;
	u64 v2 = 0x6c7967656e657261ULL ^ k0, v3 = 0x7465646279746573ULL ^ k1;
	u64 b = (u64)len << 56, m;
	size_t i, full = len & ~7UL;

	for (i = 0; i < full; i += 8) {
		m = get_unaligned_le64(d + i);
		v3 ^= m; SR(v0, v1, v2, v3); SR(v0, v1, v2, v3); v0 ^= m;
	}
	for (i = 0; i < (len & 7); i++)
		b |= (u64)d[full + i] << (8 * i);
	v3 ^= b; SR(v0, v1, v2, v3); SR(v0, v1, v2, v3); v0 ^= b;
	v2 ^= 0xff;
	SR(v0, v1, v2, v3); SR(v0, v1, v2, v3);
	SR(v0, v1, v2, v3); SR(v0, v1, v2, v3);
	return v0 ^ v1 ^ v2 ^ v3;
}

static const siphash_key_t tkey = { { 0x0706050403020100ULL, 0x0f0e0d0c0b0a0908ULL } };

static const u64 vec[] = {
	0x726fdb47dd0e0e31ULL, 0x74f839c593dc67fdULL, 0x0d6c8009d9a94f5aULL,
	0x85676696d7fb7e2dULL, 0xcf2794e0277187b7ULL, 0x18765564cd99a68dULL,
	0xcbc9466e58fee3ceULL, 0xab0200f58b01d137ULL, 0x93f5f5799a932462ULL,
};

struct abuf {
	u64 align;
	u8 b[96];
};

static void fill(u8 *p, size_t n)
{
	size_t i;

	for (i = 0; i < n; i++)
		p[i] = i;
}

static void test_known_vectors(struct kunit *test)
{
	struct abuf a;
	size_t i;

	fill(a.b, sizeof(a.b));
	for (i = 0; i < ARRAY_SIZE(vec); i++)
		KUNIT_EXPECT_EQ_MSG(test, __siphash_aligned(a.b, i, &tkey), vec[i],
				    "len %zu", i);
}

static void test_all_lengths_vs_reference(struct kunit *test)
{
	struct abuf a;
	size_t i;

	fill(a.b, sizeof(a.b));
	for (i = 0; i <= 80; i++)
		KUNIT_EXPECT_EQ_MSG(test, __siphash_aligned(a.b, i, &tkey),
				    ref_siphash(a.b, i, tkey.key[0], tkey.key[1]),
				    "len %zu", i);
}

static void test_random_keys_and_data(struct kunit *test)
{
	struct abuf a;
	siphash_key_t k;
	size_t i, j;
	u64 s = 0x123456789abcdefULL;

	for (i = 0; i < 40; i++) {
		for (j = 0; j < sizeof(a.b); j++) {
			s = s * 6364136223846793005ULL + 1442695040888963407ULL;
			a.b[j] = s >> 56;
		}
		s = s * 6364136223846793005ULL + 1442695040888963407ULL;
		k.key[0] = s;
		s = s * 6364136223846793005ULL + 1442695040888963407ULL;
		k.key[1] = s ^ (s << 32);
		KUNIT_EXPECT_EQ_MSG(test, __siphash_aligned(a.b, i * 2, &k),
				    ref_siphash(a.b, i * 2, k.key[0], k.key[1]),
				    "iter %zu", i);
	}
}

static void test_each_byte_matters(struct kunit *test)
{
	struct abuf a;
	size_t len, i;
	u64 base;

	for (len = 1; len <= 24; len++) {
		fill(a.b, sizeof(a.b));
		base = __siphash_aligned(a.b, len, &tkey);
		for (i = 0; i < len; i++) {
			a.b[i] ^= 0x01;
			KUNIT_EXPECT_NE_MSG(test, __siphash_aligned(a.b, len, &tkey), base,
					    "len %zu byte %zu", len, i);
			a.b[i] ^= 0x01;
		}
	}
}

static void test_trailing_bytes_ignored(struct kunit *test)
{
	struct abuf a;
	size_t len;
	u64 h;

	for (len = 0; len <= 24; len++) {
		fill(a.b, sizeof(a.b));
		h = __siphash_aligned(a.b, len, &tkey);
		memset(a.b + len, 0xa5, sizeof(a.b) - len);
		KUNIT_EXPECT_EQ_MSG(test, __siphash_aligned(a.b, len, &tkey), h,
				    "len %zu", len);
	}
}

static void test_length_is_mixed_in(struct kunit *test)
{
	struct abuf a;
	size_t len;

	memset(&a, 0, sizeof(a));
	for (len = 1; len <= 24; len++)
		KUNIT_EXPECT_NE_MSG(test, __siphash_aligned(a.b, len, &tkey),
				    __siphash_aligned(a.b, len - 1, &tkey),
				    "len %zu", len);
}

static void test_key_sensitivity(struct kunit *test)
{
	struct abuf a;
	siphash_key_t k0 = tkey, k1 = tkey, k2 = tkey;
	size_t len;

	fill(a.b, sizeof(a.b));
	k1.key[0] ^= 1;
	k2.key[1] ^= 1ULL << 63;
	for (len = 0; len <= 16; len++) {
		u64 h = __siphash_aligned(a.b, len, &k0);

		KUNIT_EXPECT_NE(test, h, __siphash_aligned(a.b, len, &k1));
		KUNIT_EXPECT_NE(test, h, __siphash_aligned(a.b, len, &k2));
	}
}

static void test_deterministic_and_const_input(struct kunit *test)
{
	struct abuf a, b;
	u8 copy[sizeof(a.b)];

	fill(a.b, sizeof(a.b));
	memcpy(copy, a.b, sizeof(copy));
	KUNIT_EXPECT_EQ(test, __siphash_aligned(a.b, 31, &tkey),
			__siphash_aligned(a.b, 31, &tkey));
	KUNIT_EXPECT_MEMEQ(test, a.b, copy, sizeof(copy));
	memcpy(b.b, a.b, sizeof(b.b));
	KUNIT_EXPECT_EQ(test, __siphash_aligned(a.b, 31, &tkey),
			__siphash_aligned(b.b, 31, &tkey));
}

static void test_zero_len_depends_on_key(struct kunit *test)
{
	siphash_key_t z = { { 0, 0 } };
	u8 dummy[8] __aligned(8) = { 0 };

	KUNIT_EXPECT_EQ(test, __siphash_aligned(dummy, 0, &tkey), vec[0]);
	KUNIT_EXPECT_EQ(test, __siphash_aligned(dummy, 0, &z),
			ref_siphash(dummy, 0, 0, 0));
	KUNIT_EXPECT_NE(test, __siphash_aligned(dummy, 0, &z), vec[0]);
}

static void test_siphash_wrappers(struct kunit *test)
{
	struct abuf a;

	fill(a.b, sizeof(a.b));
	KUNIT_EXPECT_EQ(test, siphash(a.b, 13, &tkey),
			__siphash_aligned(a.b, 13, &tkey));
	KUNIT_EXPECT_EQ(test, siphash(a.b + 1, 13, &tkey),
			ref_siphash(a.b + 1, 13, tkey.key[0], tkey.key[1]));
}

