 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/siphash.h>
#include <linux/unaligned.h>
#include <linux/string.h>
#include <linux/module.h>

#if !defined(CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS) && BITS_PER_LONG == 64

#define MAXLEN 80

/* Independent reference: on 64-bit, hsiphash is SipHash-1-3 truncated to u32. */
static u32 ref_hsip(const u8 *p, size_t len, const hsiphash_key_t *key)
{
	u64 v0 = SIPHASH_CONST_0, v1 = SIPHASH_CONST_1;
	u64 v2 = SIPHASH_CONST_2, v3 = SIPHASH_CONST_3;
	u64 b = (u64)len << 56, m;
	size_t i, full = len / 8;

	v3 ^= key->key[1];
	v2 ^= key->key[0];
	v1 ^= key->key[1];
	v0 ^= key->key[0];
	for (i = 0; i < full; i++) {
		m = get_unaligned_le64(p + 8 * i);
		v3 ^= m;
		SIPHASH_PERMUTATION(v0, v1, v2, v3);
		v0 ^= m;
	}
	for (i = 0; i < len % 8; i++)
		b |= (u64)p[full * 8 + i] << (8 * i);
	v3 ^= b;
	SIPHASH_PERMUTATION(v0, v1, v2, v3);
	v0 ^= b;
	v2 ^= 0xff;
	SIPHASH_PERMUTATION(v0, v1, v2, v3);
	SIPHASH_PERMUTATION(v0, v1, v2, v3);
	SIPHASH_PERMUTATION(v0, v1, v2, v3);
	return (u32)((v0 ^ v1) ^ (v2 ^ v3));
}

static const hsiphash_key_t key_a = { { 0x0706050403020100UL, 0x0f0e0d0c0b0a0908UL } };
static const hsiphash_key_t key_b = { { 0x0706050403020100UL, 0x0f0e0d0c0b0a0909UL } };
static const hsiphash_key_t key_c = { { 0x0706050403020101UL, 0x0f0e0d0c0b0a0908UL } };

static u8 buf[MAXLEN + 16] __aligned(8);

static void fill(u8 *p, size_t n, u8 seed)
{
	size_t i;

	for (i = 0; i < n; i++)
		p[i] = (u8)(i * 7 + seed);
}

static void matches_reference_all_lengths(struct kunit *test)
{
	size_t len;

	fill(buf, sizeof(buf), 1);
	for (len = 0; len <= MAXLEN; len++) {
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(buf, len, &key_a),
				    ref_hsip(buf, len, &key_a), "len=%zu", len);
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(buf, len, &key_b),
				    ref_hsip(buf, len, &key_b), "len=%zu", len);
	}
}

static void matches_unaligned_variant(struct kunit *test)
{
	size_t len;

	fill(buf, sizeof(buf), 33);
	for (len = 0; len <= MAXLEN; len++)
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(buf, len, &key_a),
				    __hsiphash_unaligned(buf, len, &key_a),
				    "len=%zu", len);
}

static void matches_hsiphash_wrapper(struct kunit *test)
{
	size_t len;

	fill(buf, sizeof(buf), 5);
	for (len = 0; len <= MAXLEN; len++)
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(buf, len, &key_c),
				    hsiphash(buf, len, &key_c), "len=%zu", len);
}

static void empty_input(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(buf, 0, &key_a),
			ref_hsip(buf, 0, &key_a));
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(buf, 0, &key_a),
			__hsiphash_aligned(buf + 8, 0, &key_a));
	KUNIT_EXPECT_NE(test, __hsiphash_aligned(buf, 0, &key_a),
			__hsiphash_aligned(buf, 0, &key_b));
}

static void block_boundaries(struct kunit *test)
{
	static const size_t lens[] = { 1, 7, 8, 9, 15, 16, 17, 23, 24, 25, 31, 32, 33 };
	int i;

	fill(buf, sizeof(buf), 99);
	for (i = 0; i < ARRAY_SIZE(lens); i++)
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(buf, lens[i], &key_a),
				    ref_hsip(buf, lens[i], &key_a), "len=%zu", lens[i]);
}

static void every_byte_matters(struct kunit *test)
{
	size_t len, i;
	u32 base;

	for (len = 1; len <= 24; len++) {
		fill(buf, sizeof(buf), 3);
		base = __hsiphash_aligned(buf, len, &key_a);
		for (i = 0; i < len; i++) {
			buf[i] ^= 0x01;
			KUNIT_EXPECT_NE_MSG(test,
					    __hsiphash_aligned(buf, len, &key_a),
					    base, "len=%zu byte=%zu", len, i);
			buf[i] ^= 0x01;
		}
		KUNIT_EXPECT_EQ(test, __hsiphash_aligned(buf, len, &key_a), base);
	}
}

static void bytes_past_len_ignored(struct kunit *test)
{
	size_t len;
	u32 h;

	for (len = 0; len <= 33; len++) {
		fill(buf, sizeof(buf), 11);
		h = __hsiphash_aligned(buf, len, &key_a);
		memset(buf + len, 0xA5, sizeof(buf) - len);
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(buf, len, &key_a),
				    h, "len=%zu", len);
		memset(buf + len, 0x00, sizeof(buf) - len);
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(buf, len, &key_a),
				    h, "len=%zu", len);
	}
}

static void length_is_mixed_in(struct kunit *test)
{
	size_t len, i;
	u32 h[41];

	/* zero-filled input: only the length differs between calls */
	memset(buf, 0, sizeof(buf));
	for (len = 0; len <= 40; len++)
		h[len] = __hsiphash_aligned(buf, len, &key_a);
	for (len = 0; len <= 40; len++)
		for (i = len + 1; i <= 40; i++)
			KUNIT_EXPECT_NE_MSG(test, h[len], h[i], "%zu vs %zu", len, i);
}

static void key_sensitivity(struct kunit *test)
{
	size_t len;

	fill(buf, sizeof(buf), 17);
	for (len = 0; len <= 20; len++) {
		u32 a = __hsiphash_aligned(buf, len, &key_a);

		KUNIT_EXPECT_NE_MSG(test, a, __hsiphash_aligned(buf, len, &key_b), "len=%zu", len);
		KUNIT_EXPECT_NE_MSG(test, a, __hsiphash_aligned(buf, len, &key_c), "len=%zu", len);
	}
}

static void high_bytes_values(struct kunit *test)
{
	size_t len;

	memset(buf, 0xff, sizeof(buf));
	for (len = 0; len <= MAXLEN; len++)
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(buf, len, &key_a),
				    ref_hsip(buf, len, &key_a), "len=%zu", len);
}

static void deterministic_and_pure(struct kunit *test)
{
	u8 copy[MAXLEN];
	u32 h1, h2;

	fill(buf, MAXLEN, 42);
	memcpy(copy, buf, MAXLEN);
	h1 = __hsiphash_aligned(buf, MAXLEN, &key_a);
	h2 = __hsiphash_aligned(buf, MAXLEN, &key_a);
	KUNIT_EXPECT_EQ(test, h1, h2);
	KUNIT_EXPECT_MEMEQ(test, buf, copy, MAXLEN);
}

static void offset_aligned_buffers(struct kunit *test)
{
	size_t off;
	u8 src[24];

	fill(src, sizeof(src), 8);
	for (off = 0; off < 16; off += 8) {
		memcpy(buf + off, src, sizeof(src));
		KUNIT_EXPECT_EQ(test, __hsiphash_aligned(buf + off, 21, &key_a),
				ref_hsip(src, 21, &key_a));
	}
}

